#!/usr/bin/env bats
# test_scripts.bats - BATS test suite for defensive Bash scripts
# Run with: bats test/test_scripts.bats

setup() {
    # Get the directory of this test file
    TEST_DIR="$(cd "$(dirname "${BATS_TEST_FILENAME}")" && pwd)"
    COMMON_UTILS="${TEST_DIR}/common_utils.sh"
    SAFE_BACKUP="${TEST_DIR}/safe_backup.sh"

    # Create temporary test directories
    TEST_TEMP_DIR="$(mktemp -d -t bats-test.XXXXXX)"
    TEST_SOURCE_DIR="${TEST_TEMP_DIR}/source"
    TEST_BACKUP_DIR="${TEST_TEMP_DIR}/backup"

    mkdir -p "${TEST_SOURCE_DIR}"
    mkdir -p "${TEST_BACKUP_DIR}"

    # Create some test files
    echo "test content 1" > "${TEST_SOURCE_DIR}/file1.txt"
    echo "test content 2" > "${TEST_SOURCE_DIR}/file2.txt"
    mkdir -p "${TEST_SOURCE_DIR}/subdir"
    echo "test content 3" > "${TEST_SOURCE_DIR}/subdir/file3.txt"
}

teardown() {
    # Clean up temporary directories
    if [[ -n "${TEST_TEMP_DIR}" ]] && [[ -d "${TEST_TEMP_DIR}" ]]; then
        rm -rf "${TEST_TEMP_DIR}"
    fi
}

# Tests for common_utils.sh

@test "common_utils.sh passes shellcheck" {
    run shellcheck --severity=warning "${COMMON_UTILS}"
    [ "$status" -eq 0 ]
}

@test "common_utils.sh is executable" {
    [ -x "${COMMON_UTILS}" ]
}

@test "common_utils.sh can be sourced" {
    source "${COMMON_UTILS}"
    [ "$(type -t log_info)" = "function" ]
}

@test "common_utils.sh provides log_info function" {
    source "${COMMON_UTILS}"
    run log_info "test message"
    [ "$status" -eq 0 ]
    [[ "$output" =~ "INFO: test message" ]]
}

@test "common_utils.sh provides log_error function" {
    source "${COMMON_UTILS}"
    run log_error "error message"
    [ "$status" -eq 0 ]
    [[ "$output" =~ "ERROR: error message" ]]
}

@test "common_utils.sh command_exists detects existing commands" {
    source "${COMMON_UTILS}"
    run command_exists "bash"
    [ "$status" -eq 0 ]
}

@test "common_utils.sh command_exists rejects non-existent commands" {
    source "${COMMON_UTILS}"
    run command_exists "definitely-not-a-real-command-12345"
    [ "$status" -eq 1 ]
}

@test "common_utils.sh validate_directory succeeds for existing directory" {
    source "${COMMON_UTILS}"
    run validate_directory "${TEST_SOURCE_DIR}"
    [ "$status" -eq 0 ]
}

@test "common_utils.sh validate_directory fails for non-existent directory" {
    source "${COMMON_UTILS}"
    run validate_directory "/nonexistent/directory/path"
    [ "$status" -ne 0 ]
}

@test "common_utils.sh create_temp_dir creates directory" {
    source "${COMMON_UTILS}"
    temp_dir="$(create_temp_dir)"
    [ -d "${temp_dir}" ]
    rm -rf "${temp_dir}"
}

@test "common_utils.sh sanitize_filename removes dangerous characters" {
    source "${COMMON_UTILS}"
    result="$(sanitize_filename "../../etc/passwd")"
    [ "$result" = "passwd" ]
}

@test "common_utils.sh sanitize_filename keeps safe characters" {
    source "${COMMON_UTILS}"
    result="$(sanitize_filename "my-file_123.txt")"
    [ "$result" = "my-file_123.txt" ]
}

# Tests for safe_backup.sh

@test "safe_backup.sh passes shellcheck" {
    run shellcheck --severity=warning "${SAFE_BACKUP}"
    [ "$status" -eq 0 ]
}

@test "safe_backup.sh is executable" {
    [ -x "${SAFE_BACKUP}" ]
}

@test "safe_backup.sh shows usage with --help" {
    run "${SAFE_BACKUP}" --help
    [ "$status" -eq 0 ]
    [[ "$output" =~ "Usage:" ]]
}

@test "safe_backup.sh fails without arguments" {
    run "${SAFE_BACKUP}"
    [ "$status" -eq 2 ]
}

@test "safe_backup.sh fails with only one argument" {
    run "${SAFE_BACKUP}" "${TEST_SOURCE_DIR}"
    [ "$status" -eq 2 ]
}

@test "safe_backup.sh creates backup in dry-run mode" {
    run "${SAFE_BACKUP}" --dry-run "${TEST_SOURCE_DIR}" "${TEST_BACKUP_DIR}"
    [ "$status" -eq 0 ]
    [[ "$output" =~ "DRY RUN" ]]
}

@test "safe_backup.sh creates actual backup" {
    run "${SAFE_BACKUP}" "${TEST_SOURCE_DIR}" "${TEST_BACKUP_DIR}"
    [ "$status" -eq 0 ]

    # Check that a backup file was created
    backup_count=$(find "${TEST_BACKUP_DIR}" -name "*.backup.*.tar.gz" | wc -l)
    [ "${backup_count}" -eq 1 ]
}

@test "safe_backup.sh creates backup with force flag when backup dir doesn't exist" {
    rm -rf "${TEST_BACKUP_DIR}"
    run "${SAFE_BACKUP}" -f "${TEST_SOURCE_DIR}" "${TEST_BACKUP_DIR}"
    [ "$status" -eq 0 ]

    # Check that backup directory was created
    [ -d "${TEST_BACKUP_DIR}" ]
}

@test "safe_backup.sh backup contains source files" {
    "${SAFE_BACKUP}" "${TEST_SOURCE_DIR}" "${TEST_BACKUP_DIR}"

    # Extract and verify backup
    backup_file=$(find "${TEST_BACKUP_DIR}" -name "*.backup.*.tar.gz" | head -n 1)
    [ -f "${backup_file}" ]

    # Create extraction directory
    extract_dir="${TEST_TEMP_DIR}/extract"
    mkdir -p "${extract_dir}"

    # Extract and verify contents
    tar -xzf "${backup_file}" -C "${extract_dir}"
    [ -f "${extract_dir}/source/file1.txt" ]
    [ -f "${extract_dir}/source/file2.txt" ]
    [ -f "${extract_dir}/source/subdir/file3.txt" ]
}

@test "safe_backup.sh verbose mode produces more output" {
    run "${SAFE_BACKUP}" -v "${TEST_SOURCE_DIR}" "${TEST_BACKUP_DIR}"
    [ "$status" -eq 0 ]
    [[ "$output" =~ "DEBUG:" ]]
}

@test "safe_backup.sh fails gracefully for non-existent source" {
    run "${SAFE_BACKUP}" "/nonexistent/source" "${TEST_BACKUP_DIR}"
    [ "$status" -ne 0 ]
    [[ "$output" =~ "ERROR:" ]]
}

@test "safe_backup.sh fails gracefully for non-existent backup dir without force" {
    rm -rf "${TEST_BACKUP_DIR}"
    run "${SAFE_BACKUP}" "${TEST_SOURCE_DIR}" "${TEST_BACKUP_DIR}"
    [ "$status" -ne 0 ]
}

@test "safe_backup.sh multiple backups creates multiple files" {
    "${SAFE_BACKUP}" "${TEST_SOURCE_DIR}" "${TEST_BACKUP_DIR}"
    sleep 1
    "${SAFE_BACKUP}" "${TEST_SOURCE_DIR}" "${TEST_BACKUP_DIR}"

    backup_count=$(find "${TEST_BACKUP_DIR}" -name "*.backup.*.tar.gz" | wc -l)
    [ "${backup_count}" -eq 2 ]
}

